            .Replace("__BRAND_ICON__",BrandIconDataUri,StringComparison.Ordinal)
            .Replace("</head>","<style>"+AdminThemeCss+"</style></head>",StringComparison.Ordinal);
        return InjectCsrf(themed,csrfToken);
    }

    public static string Login(string csrfToken,bool totpEnabled,string error="")
    {
        var totp=totpEnabled?"<label>Doğrulama kodu</label><input name='totpCode' inputmode='numeric' autocomplete='one-time-code' maxlength='6' required>":"";
        var html="""<!doctype html><html lang='tr'><head><meta charset='utf-8'><meta name='viewport' content='width=device-width,initial-scale=1'><title>Raven Map Admin</title><link rel='icon' type='image/png' href='__BRAND_ICON__'><style>*{box-sizing:border-box}body{background:#070b10;color:#eef3f7;font:14px Segoe UI,Arial;display:grid;place-items:center;min-height:100vh;margin:0}.c{width:min(410px,calc(100vw - 28px));background:#101821;border:1px solid #283744;border-radius:15px;padding:28px;box-shadow:0 22px 60px #0008}.logo{width:44px;height:44px;display:grid;place-items:center;border-radius:11px;background:#ed642f;font-weight:900;margin-bottom:18px}h2{margin:0 0 5px}.sub{color:#8ea1b0;margin-bottom:22px}label{display:block;margin:11px 0 6px;color:#b7c4cd;font-weight:650}input{width:100%;background:#0b131b;color:#fff;border:1px solid #334653;border-radius:8px;padding:11px}.remember{display:flex;gap:8px;align-items:center;font-weight:500}.remember input{width:auto}.hint{color:#8192a0;font-size:11px;line-height:1.45}.err{color:#ff7070}button{width:100%;margin-top:16px;background:#ed642f;color:#fff;border:0;border-radius:8px;padding:11px;font-weight:800;cursor:pointer}</style></head><body><div class='c'><div class='logo'><img src='__BRAND_ICON__' alt='Raven kuzgun logosu'></div><h2>Raven Map Yönetim Merkezi</h2><div class='sub'>Yönetici hesabınızla güvenli giriş yapın.</div><div class='hint'>Build __BUILD__</div><p class='err'>__ERROR__</p><form method='post'><label>Kullanıcı adı</label><input name='username' value='ravenadmin' autocomplete='username'><label>Parola</label><input name='password' type='password' autocomplete='current-password'>__TOTP__<label class='remember'><input type='checkbox' name='rememberMe' value='1' checked>Bu cihazda 30 gün hatırla</label><div class='hint'>Ortak bilgisayarda bu seçimi kapatın. Çıkış yaptığınızda güvenli oturum silinir.</div><button>Giriş Yap</button></form></div></body></html>""";
        var themed=html.Replace("__ERROR__",H(error),StringComparison.Ordinal)
            .Replace("__TOTP__",totp,StringComparison.Ordinal)
            .Replace("__BUILD__",H(BuildStamp.Id),StringComparison.Ordinal)
            .Replace("__BRAND_ICON__",BrandIconDataUri,StringComparison.Ordinal)
            .Replace("</head>","<style>"+LoginThemeCss+"</style></head>",StringComparison.Ordinal);
        return InjectCsrf(themed,csrfToken);
    }

    public static string Dashboard((int Total,int Active,int Suspended,int Revoked) s,List<LicenseRecord> licenses,List<ShopierOrderRecord> orders,List<ReleaseRecord> releases,List<AdminAuditRecord> audits,OperationalSettings operations,bool shopierEnabled,string shopierBuyUrl,IReadOnlyList<ShopierProductConfig> shopierProducts,int shopierCheckIntervalSeconds,DateTimeOffset? lastShopierPollUtc,string shopierLastError,bool shopierInitialSyncCompleted,DateTimeOffset shopierBaselineUtc,DateTimeOffset shopierCursorUtc,string serverInstanceId,string serverVersion,int databaseSchemaVersion,bool development,OwnerSettingsDocument ownerSettings,string csrfToken)
    {
        var ownerShopier=ownerSettings.Shopier??new ShopierOwnerSettings();
        var standard=(ownerShopier.Products??[]).FirstOrDefault(x=>string.Equals(x.Plan,EntitlementPlans.Standard,StringComparison.OrdinalIgnoreCase))??new ShopierOwnerProductSettings{Plan=EntitlementPlans.Standard};
        var premium=(ownerShopier.Products??[]).FirstOrDefault(x=>string.Equals(x.Plan,EntitlementPlans.Premium,StringComparison.OrdinalIgnoreCase))??new ShopierOwnerProductSettings{Plan=EntitlementPlans.Premium};
        var support=ownerSettings.Support??new SupportOwnerSettings();
        var activeAnnouncement=!string.IsNullOrWhiteSpace(operations.AnnouncementTitle)||!string.IsNullOrWhiteSpace(operations.AnnouncementMessage);
        var latestRelease=releases.OrderByDescending(x=>x.CreatedUtc).FirstOrDefault();
        var licenseCards=licenses.Count==0?Empty("Henüz lisans yok","Manuel lisans oluşturabilir veya Shopier siparişlerini senkronize edebilirsiniz."):string.Join("",licenses.Select(LicenseCard));
        var orderRows=orders.Count==0?"<tr><td colspan='7'><div class='empty'><strong>Henüz sipariş yok</strong>Shopier kontrol edildiğinde siparişler burada görünür.</div></td></tr>":string.Join("",orders.Select(o=>$"""<tr><td><b>{H(o.OrderId)}</b><br><span class='muted'>{H(o.ReceivedUtc.ToLocalTime().ToString("dd.MM.yyyy HH:mm"))}</span></td><td class='code'>{H(o.SteamId)}</td><td>{H(o.ProductTitle)}<br><span class='muted'>{H(o.ProductId)}</span></td><td>{H(o.PaymentStatus)}</td><td><span class='pill {(o.Status=="ACCEPTED"?"active":"revoked")}'>{H(OrderStatus(o.Status))}</span>{(string.IsNullOrWhiteSpace(o.Error)?"":$"<div class='bad' style='margin-top:6px'>{H(o.Error)}</div>")}</td><td>{H(o.LicenseId?.ToString()??"—")}</td><td>{(o.Status=="REJECTED"?$"<form method='post' action='/admin/shopier/orders/{Uri.EscapeDataString(o.OrderId)}/retry'><button class='secondary small'>Yeniden İşle</button></form>":"—")}</td></tr>"""));
        var releaseRows=releases.Count==0?"<tr><td colspan='8'><div class='empty'><strong>Henüz sürüm yayınlanmadı</strong>İlk güncelleme paketini üstteki formdan yayınlayabilirsiniz.</div></td></tr>":string.Join("",releases.Select(r=>$"""<tr><td><b>v{H(r.Version)}</b></td><td><span class='pill {(r.Mandatory?"revoked":"active")}'>{(r.Mandatory?"ZORUNLU":"NORMAL")}</span></td><td>v{H(r.MinimumVersion)}</td><td>{H(r.FileName)}</td><td class='code' title='{H(r.Sha256)}'>{H(Short(r.Sha256,18))}</td><td>{H(r.CreatedUtc.ToLocalTime().ToString("dd.MM.yyyy HH:mm"))}</td><td>{H(string.IsNullOrWhiteSpace(r.Notes)?"—":r.Notes)}</td><td><form method='post' action='/admin/releases/{Uri.EscapeDataString(r.Version)}/delete' data-confirm='v{H(r.Version)} client sürümü ve sunucudaki paketi silinecek. Devam edilsin mi?'><button class='danger small'>Sürümü Sil</button></form></td></tr>"""));
        var auditRows=audits.Count==0?"<tr><td colspan='6'><div class='empty'>İşlem kaydı yok.</div></td></tr>":string.Join("",audits.Select(a=>$"""<tr><td>{H(a.CreatedUtc.ToLocalTime().ToString("dd.MM.yyyy HH:mm:ss"))}</td><td>{H(a.Actor)}</td><td><span class='pill'>{H(AuditLabel(a.Action))}</span></td><td>{H(a.Target)}</td><td>{H(a.Detail)}</td><td class='code'>{H(a.RemoteIp)}</td></tr>"""));
        var productRows=shopierProducts.Count==0?"<div class='callout warning'>Shopier için etkin ürün eşlemesi bulunmuyor.</div>":string.Join("",shopierProducts.Select(p=>$"""<div class='card soft'><div class='row' style='justify-content:space-between'><b>{H(p.Plan)}</b><span class='pill active'>ETKİN</span></div><div class='muted' style='margin-top:8px'>{H(p.Title)}</div><div class='license-meta'><span>Ürün: {H(p.ProductId)}</span><span>Fiyat: {H(string.IsNullOrWhiteSpace(p.ExpectedUnitPrice)?"Kontrol yok":p.ExpectedUnitPrice+" "+p.ExpectedCurrency)}</span><span>Süre: {(p.LicenseDays<=0?"Süresiz":p.LicenseDays+" gün")}</span></div></div>"""));
        var apiKeyState=string.IsNullOrWhiteSpace(ownerShopier.ApiKey)?"Kayıtlı değil":$"Güvenli biçimde kayıtlı ({ownerShopier.ApiKey.Trim().Length} karakter)";
        var starts=operations.AnnouncementStartsUtc?.ToLocalTime().ToString("yyyy-MM-ddTHH:mm")??"";var ends=operations.AnnouncementEndsUtc?.ToLocalTime().ToString("yyyy-MM-ddTHH:mm")??"";var imageCount=SplitUrls(operations.AnnouncementImageUrl).Count;var homeMediaCount=SplitUrls(operations.HomeMediaUrls).Count;

        var overview=$"""<section id='overview' class='admin-section'><div class='section-title'><div><h2>Genel Bakış</h2><p>Sistemin güncel durumunu tek bakışta görün.</p></div></div><div class='grid metrics'>{Metric("Toplam lisans",s.Total.ToString(),"")}{Metric("Aktif",s.Active.ToString(),"ok")}{Metric("Askıda / İptal",$"{s.Suspended} / {s.Revoked}",s.Revoked>0?"warn":"")}{Metric("Shopier siparişi",orders.Count.ToString(),"")}</div><div class='grid two'><div class='card'><div class='card-label'>Sunucu</div><h3 style='margin-top:8px'>Raven API v{H(serverVersion)}</h3><div class='muted'>Build {H(BuildStamp.Id)} · Veritabanı şeması v{databaseSchemaVersion}</div><div class='code muted' style='margin-top:10px'>Kimlik: {H(Short(serverInstanceId,28))}</div><div class='callout' style='margin-top:14px'>HTTPS merkezi: <b>api.ravenrusttr.com.tr</b></div></div><div class='card'><div class='card-label'>Dağıtım</div><h3 style='margin-top:8px'>{(latestRelease is null?"Henüz sürüm yok":$"Son sürüm: v{H(latestRelease.Version)}")}</h3><div class='muted'>{(latestRelease is null?"İlk paketi Güncellemeler bölümünden yayınlayın.":$"{H(latestRelease.CreatedUtc.ToLocalTime().ToString("dd.MM.yyyy HH:mm"))} · {(latestRelease.Mandatory?"Zorunlu":"Normal")} güncelleme")}</div><button type='button' class='secondary small' data-section='updates' style='margin-top:14px'>Güncellemeleri yönet</button></div><div class='card'><div class='card-label'>Duyuru</div><h3 style='margin-top:8px'>{(activeAnnouncement?H(operations.AnnouncementTitle):"Yayınlanan duyuru yok")}</h3><div class='muted'>{(activeAnnouncement?H(Short(operations.AnnouncementMessage,120)):"Client başlangıç ekranında gösterilecek duyuruyu oluşturabilirsiniz.")}</div><button type='button' class='secondary small' data-section='operations' style='margin-top:14px'>Duyuruyu yönet</button></div><div class='card'><div class='card-label'>Shopier</div><h3 class='{(shopierEnabled?"ok":"bad")}' style='margin-top:8px'>{(shopierEnabled?"Bağlantı etkin":"Bağlantı kapalı")}</h3><div class='muted'>Son başarılı kontrol: {H(lastShopierPollUtc?.ToLocalTime().ToString("dd.MM.yyyy HH:mm:ss")??"Henüz yok")}</div>{(string.IsNullOrWhiteSpace(shopierLastError)?"":$"<div class='bad' style='margin-top:7px'>{H(shopierLastError)}</div>")}</div></div></section>""";
        var licensesSection=$"""<section id='licenses' class='admin-section'><div class='section-title'><div><h2>Lisans Yönetimi</h2><p>Yeni yetki oluşturun, aktif lisansları yönetin ve iptal edilen kayıtları kaldırın.</p></div></div><div class='card' style='margin-bottom:14px'><h3>Manuel lisans oluştur</h3><form method='post' action='/admin/licenses/create' class='form-grid four' style='margin-top:12px'><div class='field'><label>SteamID64</label><input name='steamId' placeholder='7656119...' required></div><div class='field'><label>Paket</label><select name='plan'><option value='STANDARD'>Standard</option><option value='PREMIUM'>Premium</option></select></div><div class='field'><label>Süre</label><input name='days' type='number' value='30'><small>0 veya negatif: süresiz</small></div><div class='field'><label>Yönetici notu</label><input name='note' placeholder='Örn. destek telafisi'></div><div><button>Yetki Oluştur</button></div></form></div><div class='card'><div class='toolbar'><input id='licenseSearch' placeholder='SteamID, sipariş, cihaz veya not ara...'><select id='licenseStatus'><option value=''>Tüm durumlar</option><option value='ACTIVE'>Aktif</option><option value='SUSPENDED'>Askıda</option><option value='REVOKED'>İptal edildi</option></select></div><div class='license-list'>{licenseCards}</div></div></section>""";
        var ordersSection=$"""<section id='orders' class='admin-section'><div class='section-title'><div><h2>Siparişler</h2><p>Shopier bağlantısını ve siparişlerin lisansa dönüşme durumunu izleyin.</p></div><form method='post' action='/admin/shopier/check'><button class='secondary'>Şimdi Senkronize Et</button></form></div><div class='grid three' style='margin-bottom:14px'>{Metric("Bağlantı",shopierEnabled?"Etkin":"Kapalı",shopierEnabled?"ok":"bad")}{Metric("İlk senkronizasyon",shopierInitialSyncCompleted?"Tamamlandı":"Bekliyor",shopierInitialSyncCompleted?"ok":"warn")}{Metric("Kontrol aralığı",shopierCheckIntervalSeconds+" saniye","")}</div><div class='card' style='margin-bottom:14px'><div class='grid two'><div><h3>Shopier durumu</h3><div class='muted'>Satın alma: {H(shopierBuyUrl)}</div><div class='muted' style='margin-top:6px'>Başlangıç: {H(shopierBaselineUtc.ToLocalTime().ToString("dd.MM.yyyy HH:mm:ss"))}</div><div class='muted'>İşlem imleci: {H(shopierCursorUtc.ToLocalTime().ToString("dd.MM.yyyy HH:mm:ss"))}</div>{(string.IsNullOrWhiteSpace(shopierLastError)?"":$"<div class='callout warning' style='margin-top:10px'>{H(shopierLastError)}</div>")}</div><div><h3>Etkin paket eşlemeleri</h3><div class='grid two' style='margin-top:10px'>{productRows}</div></div></div></div>{(development?$"""<div class='card' style='margin-bottom:14px'><h3>Test siparişi <span class='pill warn'>YALNIZ GELİŞTİRME</span></h3><form method='post' action='/admin/shopier/test-order' class='row' style='margin-top:12px'><input name='steamId' placeholder='SteamID64' required style='max-width:240px'><select name='plan' style='max-width:160px'><option value='STANDARD'>Standard</option><option value='PREMIUM'>Premium</option></select><input name='orderId' placeholder='İsteğe bağlı test sipariş no' style='max-width:260px'><button>Test Siparişi Oluştur</button></form></div>""":"")}<div class='card'><div class='table-wrap'><table class='table'><thead><tr><th>Sipariş / Tarih</th><th>SteamID64</th><th>Ürün</th><th>Ödeme</th><th>Sonuç</th><th>Lisans</th><th>İşlem</th></tr></thead><tbody>{orderRows}</tbody></table></div></div></section>""";
        var operationsSection=$"""<section id='operations' class='admin-section'><div class='section-title'><div><h2>Ana Sayfa, Duyuru ve Bakım</h2><p>Client ana kapağını, duyuru alanını ve bakım mesajını tek yerden yönetin.</p></div></div><form method='post' action='/admin/operations/update' class='grid two'><div class='card'><div class='row' style='justify-content:space-between'><div><h3>Bakım modu</h3><div class='muted'>Etkin olduğunda client kullanıcıları bilgilendirilir.</div></div><label class='check'><input type='checkbox' name='maintenanceEnabled' value='1' {(operations.MaintenanceEnabled?"checked":"")}>Etkin</label></div><div class='field' style='margin-top:15px'><label>Kullanıcıya gösterilecek mesaj</label><textarea name='maintenanceMessage' rows='4' placeholder='Planlı bakım nedeniyle hizmet geçici olarak kullanılamıyor.'>{H(operations.MaintenanceMessage)}</textarea></div></div><div class='card'><h3>Duyuru ön izlemesi</h3>{(activeAnnouncement?$"""<div class='announcement-preview' style='margin-top:12px'><span class='pill'>{H(operations.AnnouncementLevel)}</span><h4>{H(operations.AnnouncementTitle)}</h4><div class='muted'>{H(operations.AnnouncementMessage)}</div><div class='license-meta'><span>{imageCount} medya</span><span>{H(operations.AnnouncementStartsUtc?.ToLocalTime().ToString("dd.MM.yyyy HH:mm")??"Hemen")}</span><span>{H(operations.AnnouncementEndsUtc?.ToLocalTime().ToString("dd.MM.yyyy HH:mm")??"Süresiz")}</span></div></div>""":Empty("Aktif duyuru yok","Aşağıdaki alanları doldurarak yeni bir duyuru yayınlayın."))}</div><div class='card' style='grid-column:1/-1'><div class='row' style='justify-content:space-between'><div><h3>Ana sayfa kapakları</h3><div class='muted'>Client açılışındaki büyük görsel alanını buradan değiştirin.</div></div><span class='pill active'>{homeMediaCount} medya</span></div><div class='field' style='margin-top:13px'><label>Kapak fotoğrafı adresleri</label><textarea name='homeMediaUrls' rows='5' placeholder='https://site.com/kapak-1.jpg, https://site.com/kapak-2.png'>{H(operations.HomeMediaUrls)}</textarea><small>Virgülle veya satır satır HTTPS fotoğraf adresi ekleyebilirsiniz. JPG ve PNG önerilir. Boş bırakırsanız yerleşik kapak fotoğrafları gösterilir.</small></div></div><div class='card' style='grid-column:1/-1'><h3>Client duyurusu</h3><div class='form-grid' style='margin-top:13px'><div class='field'><label>Başlık</label><input name='announcementTitle' value='{H(operations.AnnouncementTitle)}' placeholder='Örn. Raven 1.0.2 yayınlandı'></div><div class='field'><label>Önem seviyesi</label><select name='announcementLevel'><option value='INFO' {Selected(operations.AnnouncementLevel,"INFO")}>Bilgi</option><option value='UPDATE' {Selected(operations.AnnouncementLevel,"UPDATE")}>Güncelleme</option><option value='WARNING' {Selected(operations.AnnouncementLevel,"WARNING")}>Uyarı</option><option value='CRITICAL' {Selected(operations.AnnouncementLevel,"CRITICAL")}>Kritik</option></select></div><div class='field'><label>Başlangıç (isteğe bağlı)</label><input type='datetime-local' name='announcementStarts' value='{H(starts)}'></div><div class='field'><label>Bitiş (isteğe bağlı)</label><input type='datetime-local' name='announcementEnds' value='{H(ends)}'></div></div><div class='field' style='margin-top:12px'><label>Duyuru metni</label><textarea name='announcementMessage' rows='5' placeholder='Kullanıcının görmesi gereken açıklama...'>{H(operations.AnnouncementMessage)}</textarea></div><div class='field' style='margin-top:12px'><label>Duyuru fotoğrafı adresleri</label><textarea name='announcementImageUrl' rows='4' placeholder='https://site.com/duyuru-1.jpg, https://site.com/duyuru-2.png'>{H(operations.AnnouncementImageUrl)}</textarea><small>Virgülle veya satır satır HTTPS fotoğraf adresi ekleyebilirsiniz. Bu fotoğraflar yalnızca alttaki duyuru kartında gösterilir.</small></div><div class='row' style='margin-top:14px'><button>Ana Sayfa, Bakım ve Duyuruyu Kaydet</button></form>{(activeAnnouncement?"<form method='post' action='/admin/announcement/delete' data-confirm='Yayınlanan duyuru kaldırılacak. Devam edilsin mi?'><button class='danger'>Duyuruyu Kaldır</button></form>":"")}</div></div></section>""";
        var updatesSection=$"""<section id='updates' class='admin-section'><div class='section-title'><div><h2>Client Güncellemeleri</h2><p>İmzalı Raven paketini yayınlayın ve mevcut sürümleri izleyin.</p></div></div><div class='grid two'><div class='card'><div class='card-label'>1 · SÜRÜM BİLGİSİ</div><h3 style='margin-top:7px'>Yeni güncelleme yayınla</h3><form method='post' action='/admin/releases/upload' enctype='multipart/form-data' style='margin-top:14px'><div class='form-grid'><div class='field'><label>Yeni sürüm</label><input name='version' placeholder='1.0.1' required></div><div class='field'><label>En düşük desteklenen client</label><input name='minimumVersion' placeholder='1.0.0'></div></div><label class='check' style='margin-top:14px'><input type='checkbox' name='mandatory' value='1'>Bu güncellemeyi zorunlu yap</label><div class='separator' style='margin:16px 0'></div><div class='card-label'>2 · DOSYALAR</div><div class='grid two' style='margin-top:10px'><div class='file-box'><input type='file' name='package' accept='.ravenpkg' required data-file-label='packageName'><strong>Güncelleme paketi</strong><span class='muted'>RavenMapPanel_Update_vX.Y.Z.ravenpkg</span><span id='packageName' class='filename'>Henüz paket seçilmedi</span></div><div class='file-box'><input type='file' name='signatureFile' accept='.sig' required data-file-label='signatureName'><strong>Dijital imza</strong><span class='muted'>Aynı pakete ait .ravenpkg.sig dosyası</span><span id='signatureName' class='filename'>Henüz imza seçilmedi</span></div></div><div class='callout warning' style='margin-top:12px'><b>Bu alana yüklemeyin:</b> .sha256, manifest.json ve artifact-info.json. Sunucu paketin SHA-256 değerini kendisi hesaplar.</div><div class='field' style='margin-top:12px'><label>Kullanıcıya gösterilecek değişiklik notları</label><textarea name='notes' rows='5' placeholder='• Güncelleyici iyileştirildi&#10;• Uygulama güncelleme sonrası otomatik açılır'></textarea></div><button style='margin-top:14px'>Paketi Doğrula ve Yayınla</button></form></div><div class='card'><div class='card-label'>YAYIN AKIŞI</div><h3 style='margin-top:7px'>Doğru dosyayı nasıl seçerim?</h3><div class='stack' style='margin-top:14px'><div class='callout'><b>1.</b> Client çıkış klasöründeki <b>.ravenpkg</b> dosyasını seçin.</div><div class='callout'><b>2.</b> Yanındaki aynı isimli <b>.sig</b> dosyasını seçin.</div><div class='callout'><b>3.</b> Sunucu imzayı ve paketi doğrular; geçerliyse HTTPS üzerinden yayınlar.</div></div><div class='callout warning' style='margin-top:14px'><b>Sürüm sıfırlama:</b> 1.0.0 yayınlamadan önce eski 1.7.x kayıtlarını aşağıdaki “Sürümü Sil” düğmesiyle kaldırın. Mevcut 1.7.x kurulumlara bir kez tam 1.0.0 kurulumu verin.</div></div></div><div class='card' style='margin-top:14px'><h3>Yayınlanan sürümler</h3><div class='table-wrap' style='margin-top:12px'><table class='table'><thead><tr><th>Sürüm</th><th>Tür</th><th>Minimum</th><th>Paket dosyası</th><th>SHA-256</th><th>Yayın</th><th>Notlar</th><th>İşlem</th></tr></thead><tbody>{releaseRows}</tbody></table></div></div></section>""";
        var settingsSection=$"""<section id='settings' class='admin-section'><div class='section-title'><div><h2>Sistem Ayarları</h2><p>Shopier, ürün paketleri ve client destek adresini yönetin.</p></div></div><form method='post' action='/admin/settings/business' class='stack'><div class='card'><div class='row' style='justify-content:space-between'><div><h3>Shopier bağlantısı</h3><div class='muted'>Değişiklikler sunucu yeniden başlatılmadan uygulanır.</div></div><label class='check'><input type='checkbox' name='shopierEnabled' value='1' {(ownerShopier.Enabled?"checked":"")}>Otomatik lisans etkin</label></div><div class='form-grid' style='margin-top:14px'><div class='field'><label>Shopier mağaza adresi</label><input name='shopierBuyUrl' value='{H(ownerShopier.BuyUrl)}' placeholder='https://www.shopier.com/ravenrust'></div><div class='field'><label>Shopier API adresi</label><input name='shopierApiUrl' value='{H(ownerShopier.ApiUrl)}' placeholder='https://api.shopier.com/v1/orders'></div><div class='field'><label>Yeni API anahtarı</label><input type='password' name='shopierApiKey' autocomplete='new-password' placeholder='Değiştirmiyorsanız boş bırakın'><small>{H(apiKeyState)}. Güvenlik için mevcut anahtar görüntülenmez.</small></div><div class='field'><label>Kontrol aralığı (saniye)</label><input type='number' min='30' name='shopierCheckIntervalSeconds' value='{ownerShopier.CheckIntervalSeconds}'></div></div></div><div class='grid two'><div class='card'>{ProductSettings("STANDARD",standard,"standard")}</div><div class='card'>{ProductSettings("PREMIUM",premium,"premium")}</div></div><div class='card'><h3>Kullanıcı desteği</h3><div class='form-grid' style='margin-top:13px'><div class='field'><label>Destek adresi</label><input name='supportUrl' value='{H(support.Url)}' placeholder='https://discord.gg/...'></div><div class='field'><label>Buton adı</label><input name='supportLabel' value='{H(support.Label)}' placeholder='Discord Destek'></div></div><div class='field' style='margin-top:12px'><label>Destek açıklaması</label><textarea name='supportMessage' rows='4'>{H(support.Message)}</textarea></div></div><div><button>Ayarları Kaydet ve Uygula</button></div></form></section>""";
        var auditsSection=$"""<section id='audits' class='admin-section'><div class='section-title'><div><h2>Admin İşlem Kayıtları</h2><p>Girişler, lisans değişiklikleri ve yayın işlemleri denetim için saklanır.</p></div></div><div class='card'><div class='callout' style='margin-bottom:12px'>Kayıtlar güvenlik geçmişidir. Lisans kalıcı olarak silinse bile hangi yöneticinin ne yaptığı burada kalır.</div><div class='table-wrap'><table class='table'><thead><tr><th>Zaman</th><th>Yönetici</th><th>İşlem</th><th>Hedef</th><th>Açıklama</th><th>IP</th></tr></thead><tbody>{auditRows}</tbody></table></div></div></section>""";
        return Layout("Raven Yönetim Merkezi",overview+licensesSection+ordersSection+operationsSection+updatesSection+settingsSection+auditsSection,csrfToken).Replace("__LICENSE_COUNT__",s.Total.ToString(),StringComparison.Ordinal).Replace("__ORDER_COUNT__",orders.Count.ToString(),StringComparison.Ordinal).Replace("__RELEASE_COUNT__",releases.Count.ToString(),StringComparison.Ordinal);
    }

    private static string LicenseCard(LicenseRecord l)
    {
        var search=H($"{l.Id} {l.SteamId} {l.ShopierOrderId} {l.DeviceHash} {l.Note} {l.StatusReason}".ToLower(new System.Globalization.CultureInfo("tr-TR")));
        var delete=l.Status=="REVOKED"?$"""<form method='post' action='/admin/licenses/{l.Id}/delete' data-confirm='#{l.Id} numaralı iptal edilmiş lisans kalıcı olarak silinecek. Sipariş geçmişi korunur. Devam edilsin mi?'><input type='hidden' name='confirmation' value='DELETE'><button class='danger small'>Kalıcı Sil</button></form>""":"";
        var planButton=l.Plan==EntitlementPlans.Premium
            ? "<button class='secondary small' name='action' value='plan_standard'>Standard Yap</button>"
            : "<button class='secondary small' name='action' value='plan_premium'>Premium Yap</button>";
        var statusButton=l.Status=="ACTIVE"
            ? "<button class='danger small' name='action' value='suspend'>Askıya Al</button>"
            : "<button class='small' name='action' value='activate'>Aktif Et</button>";
        var reason=string.IsNullOrWhiteSpace(l.StatusReason)?"":$"<div class='bad' style='margin-top:6px'>Neden: {H(l.StatusReason)}</div>";

        return $"""
<article class='license' data-license data-status='{H(l.Status)}' data-search='{search}'>
  <div class='license-top'>
    <div class='license-main'><div class='license-id'>#{l.Id}</div><div>
      <div class='license-name'>{H(l.SteamId??"Steam hesabı bağlanmadı")}</div>
      <div class='license-meta'><span class='pill {StatusClass(l.Status)}'>{H(StatusLabel(l.Status))}</span><span class='pill {(l.Plan==EntitlementPlans.Premium?"premium":"")}'>{H(l.Plan)}</span><span>{H(l.Source)}</span><span>Bitiş: {H(l.ExpiresUtc?.ToLocalTime().ToString("dd.MM.yyyy")??"Süresiz")}</span><span>Client: {H(string.IsNullOrWhiteSpace(l.LastClientVersion)?"—":l.LastClientVersion)}</span></div>{reason}
    </div></div>
    <div class='muted code' title='{H(l.DeviceHash)}'>Cihaz: {H(Short(l.DeviceHash))}</div>
  </div>
  <div class='license-actions'>
    <form method='post' action='/admin/licenses/{l.Id}/action'><div class='row'>
      <input name='reason' value='{H(l.StatusReason)}' placeholder='Askıya alma / iptal nedeni'>
      <div class='actions'><button class='secondary small' name='action' value='reset_device'>Cihazı Sıfırla</button><button class='secondary small' name='action' value='add30'>+30 Gün</button>{planButton}{statusButton}<button class='danger small' name='action' value='revoke'>İptal Et</button></div>
    </div></form>
    <div class='actions'>{delete}</div>
  </div>
</article>
""";
    }
    private static string ProductSettings(string title,ShopierOwnerProductSettings p,string prefix)=>$"""<div class='row' style='justify-content:space-between'><div><h3>{title} paketi</h3><div class='muted'>Shopier ürününün lisans karşılığı</div></div><label class='check'><input type='checkbox' name='{prefix}Enabled' value='1' {(p.Enabled?"checked":"")}>Etkin</label></div><div class='form-grid' style='margin-top:13px'><div class='field'><label>Product ID</label><input name='{prefix}ProductId' value='{H(p.ProductId)}'></div><div class='field'><label>Ürün adı</label><input name='{prefix}Title' value='{H(p.Title)}'></div><div class='field'><label>Beklenen fiyat (TRY)</label><input name='{prefix}Price' value='{H(p.ExpectedUnitPrice)}'></div><div class='field'><label>Lisans süresi (gün)</label><input type='number' name='{prefix}Days' value='{p.LicenseDays}'><small>0: süresiz</small></div></div>""";
    private static string Metric(string label,string value,string cls)=>$"<div class='card'><div class='card-label'>{H(label)}</div><div class='metric {H(cls)}'>{H(value)}</div></div>";
    private static string Empty(string title,string text)=>$"<div class='empty'><strong>{H(title)}</strong>{H(text)}</div>";
    private static string StatusClass(string status)=>status switch{"ACTIVE"=>"active","SUSPENDED"=>"suspended","REVOKED"=>"revoked",_=>""};
    private static string StatusLabel(string status)=>status switch{"ACTIVE"=>"AKTİF","SUSPENDED"=>"ASKIDA","REVOKED"=>"İPTAL EDİLDİ","EXPIRED"=>"SÜRESİ DOLDU",_=>status};
    private static string OrderStatus(string status)=>status switch{"ACCEPTED"=>"LİSANSA DÖNÜŞTÜ","REJECTED"=>"REDDEDİLDİ","PENDING"=>"BEKLİYOR",_=>status};
    private static string AuditLabel(string action)=>action switch{"LOGIN_SUCCESS"=>"Giriş","LOGIN_FAILED"=>"Başarısız giriş","LICENSE_CREATE"=>"Lisans oluşturuldu","LICENSE_ACTION"=>"Lisans değiştirildi","LICENSE_DELETE"=>"Lisans silindi","RELEASE_UPLOAD"=>"Sürüm yayınlandı","RELEASE_DELETE"=>"Sürüm silindi","RELEASE_DELETE_FILE_WARNING"=>"Sürüm dosyası uyarısı","OPERATIONS_UPDATE"=>"Duyuru/Bakım","ANNOUNCEMENT_DELETE"=>"Duyuru kaldırıldı","BUSINESS_SETTINGS_UPDATE"=>"Ayar değişti",_=>action};
    private static string Selected(string current,string value)=>string.Equals(current,value,StringComparison.OrdinalIgnoreCase)?"selected":"";
    private static List<string> SplitUrls(string? raw)=>(raw??"").Replace("\r","",StringComparison.Ordinal).Split('\n',StringSplitOptions.RemoveEmptyEntries|StringSplitOptions.TrimEntries).ToList();
    private static string InjectCsrf(string html,string csrfToken){var hidden=$"<input type='hidden' name='__RequestVerificationToken' value='{H(csrfToken)}'>";return Regex.Replace(html,@"(<form\b[^>]*\bmethod='post'[^>]*>)","$1"+hidden,RegexOptions.IgnoreCase);}
    private static string Short(string? value,int length=14)=>string.IsNullOrWhiteSpace(value)?"—":value.Length<=length?value:value[..length]+"…";
    private static string H(string? value)=>WebUtility.HtmlEncode(value??"");
}
